package com.clavis.reader;
import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.media.*;
import android.media.audiofx.*;
import android.media.session.*;
import android.net.Uri;
import android.os.*;
import java.util.*;
import java.util.concurrent.*;

public class PlaybackService extends Service {
 static PlaybackService live;static String playbackError="";
 MediaPlayer player;String uri="",title="";boolean ready=false,sleepAtChapterEnd=false;float speed=1f;int chapterIndex;
 Book book;Equalizer equalizer;LoudnessEnhancer loudness;
 private MediaSession session;private AudioManager manager;private AudioFocusRequest focus;private Bitmap cover;
 private final ExecutorService chapters=Executors.newSingleThreadExecutor();private int metadataVersion;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService artwork=Executors.newSingleThreadExecutor();
 private long pausedAt=0,lastSeek=-1;private int lastSeekChapter=0;private boolean loading=false;
 private final Runnable save=new Runnable(){public void run(){persist();handler.postDelayed(this,5000);}};
 private final Runnable boundary=new Runnable(){public void run(){if(playing()&&book.trackEnd(chapterIndex)>=0&&player.getCurrentPosition()>=book.trackEnd(chapterIndex))completeChapter();handler.postDelayed(this,100);}};
 private void completeChapter(){if(!ready)return;player.pause();persist();boolean autoplay=!sleepAtChapterEnd;sleepAtChapterEnd=false;if(chapterIndex+1<book.chapterCount()){chapterIndex++;loadChapter(0,autoplay);}else if(autoplay&&PlayerDialogs.prefs(this).getBoolean("nextBook",false))nextBook();else notice();}
 void replaceChapters(Book updated){boolean active=playing();book=updated;chapterIndex=updated.chapterIndex;loadChapter(updated.position,active);}
 private final Runnable sleepTask=()->{sleepAtChapterEnd=false;pause();};
 private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 @Override public void onCreate(){super.onCreate();live=this;manager=(AudioManager)getSystemService(AUDIO_SERVICE);AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attrs).setOnAudioFocusChangeListener(c->{if(c<0)pause();}).build();session=new MediaSession(this,"Clavis");session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onSkipToNext(){jumpChapter(chapterIndex+1,0);}public void onSkipToPrevious(){jumpChapter(chapterIndex-1,0);}public void onSeekTo(long p){seek(p);}});session.setActive(true);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("playback","Audiobook playback",NotificationManager.IMPORTANCE_LOW));registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));handler.post(save);handler.post(boundary);}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();if("toggle".equals(action)){if(playing())pause();else play();return START_NOT_STICKY;}if("back".equals(action)){skip(-skipSeconds());return START_NOT_STICKY;}if("forward".equals(action)){skip(skipSeconds());return START_NOT_STICKY;}String next=intent.getStringExtra("uri");if(next!=null&&(!next.equals(uri)||(!ready&&!loading))){persist();Book selected=null;for(Book b:Store.load(this))if(b.uri.equals(next))selected=b;if(selected!=null)loadBook(selected,intent.getBooleanExtra("autoplay",true));}return START_NOT_STICKY;}
 private void loadBook(Book selected){loadBook(selected,true);}
 private void loadBook(Book selected,boolean autoplay){getSharedPreferences("navigation",0).edit().putString(selected.author.equals("Podcast")?"lastPodcastUri":"lastAudioUri",selected.uri).apply();book=selected;uri=book.uri;title=book.title;speed=book.speed;chapterIndex=book.chapterIndex;cover=null;pausedAt=0;String requested=uri;artwork.execute(()->{Bitmap result=Artwork.load(this,selected);handler.post(()->{if(uri.equals(requested)){cover=result;metadata();notice();}else if(result!=null)result.recycle();});});loadChapter(book.position,autoplay);}
 private void releaseEffects(){if(equalizer!=null){equalizer.release();equalizer=null;}if(loudness!=null){loudness.release();loudness=null;}}
 private void loadChapter(long resume,boolean autoplay){
  playbackError="";ready=false;loading=true;releaseEffects();if(player!=null)player.release();player=new MediaPlayer();MediaPlayer opening=player;notice();
  try{player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setDataSource(this,Uri.parse(book.trackUri(chapterIndex)));player.setOnPreparedListener(p->{if(p!=opening)return;ready=true;loading=false;p.seekTo((int)(book.trackStart(chapterIndex)+Math.min(resume,duration())));p.setVolume(PlayerDialogs.prefs(this).getInt("volume",80)/100f,PlayerDialogs.prefs(this).getInt("volume",80)/100f);metadata();try{ensureEffects();}catch(Exception ignored){}if(autoplay)play();else notice();persist();discoverChapters();});player.setOnCompletionListener(p->{if(p==opening)completeChapter();});player.setOnErrorListener((p,w,e)->{playbackError="This chapter could not be played. Choose another chapter or import the folder again.";ready=false;loading=false;stopForeground(STOP_FOREGROUND_REMOVE);return true;});player.prepareAsync();}catch(Exception e){playbackError="Unable to open this chapter. Check folder access and import it again.";ready=false;loading=false;stopForeground(STOP_FOREGROUND_REMOVE);}
 }
 void discoverChapters(){if(book==null||!ChapterDetection.needs(book))return;Book selected=book;int version=++metadataVersion;chapters.execute(()->{try{ChapterDetection.Discovery found=ChapterDetection.read(getContentResolver(),selected);handler.post(()->{if(live!=this||book!=selected||version!=metadataVersion||!ready)return;persist();ChapterDetection.save(this,selected,found);chapterIndex=selected.chapterIndex;lastSeek=-1;metadata();notice();});}catch(Exception ignored){}});}
 void nextBook(){ArrayList<Book> books=Store.load(this);boolean found=false;for(Book b:books){if(found&&book!=null&&b.author.equals(book.author)){loadBook(b);return;}if(b.uri.equals(uri))found=true;}notice();}
 void jumpChapter(int index,long position){if(book==null||index<0||index>=book.chapterCount())return;persist();chapterIndex=index;pausedAt=0;loadChapter(position,true);}
 int chapterCount(){return book==null?1:book.chapterCount();}String chapterTitle(){return book==null?"":book.trackTitle(chapterIndex);}
 boolean playing(){return ready&&player!=null&&player.isPlaying();}long position(){return ready?Math.max(0,Math.min(duration(),player.getCurrentPosition()-book.trackStart(chapterIndex))):0;}long duration(){return ready?book.trackLength(chapterIndex,player.getDuration()):0;}
 void play(){if(ready&&manager.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED){int rewind=PlayerDialogs.prefs(this).getInt("rewind",0);if(pausedAt>0&&SystemClock.elapsedRealtime()-pausedAt>1500&&rewind>0)player.seekTo((int)(book.trackStart(chapterIndex)+Math.max(0,position()-rewind*1000L)));pausedAt=0;player.start();setSpeed(speed);notice();}}
 void pause(){if(ready){player.pause();pausedAt=SystemClock.elapsedRealtime();}persist();notice();}
 void seek(long p){if(ready){lastSeek=position();lastSeekChapter=chapterIndex;player.seekTo((int)(book.trackStart(chapterIndex)+Math.max(0,Math.min(duration(),p))));persist();notice();}}
 void undoSeek(){if(lastSeek<0)return;long p=lastSeek;int chapter=lastSeekChapter;lastSeek=-1;if(chapter==chapterIndex){if(ready)player.seekTo((int)(book.trackStart(chapterIndex)+p));}else jumpChapter(chapter,p);persist();}
 int skipSeconds(){return PlayerDialogs.prefs(this).getInt("skip",30);}
 void skip(int seconds){if(!ready)return;long target=position()+seconds*1000L;lastSeek=position();lastSeekChapter=chapterIndex;if(target>=duration()&&chapterIndex+1<chapterCount())jumpChapter(chapterIndex+1,target-duration());else if(target<0&&chapterIndex>0)jumpChapter(chapterIndex-1,0);else seek(target);}
 void setSpeed(float s){speed=s;if(ready){boolean wasPlaying=playing();player.setPlaybackParams(player.getPlaybackParams().setSpeed(s));if(!wasPlaying)player.pause();persist();notice();}}
 void setSleep(int minutes){sleepAtChapterEnd=false;handler.removeCallbacks(sleepTask);if(minutes>0)handler.postDelayed(sleepTask,minutes*60000L);}
 void ensureEffects(){if(!ready)return;if(equalizer==null){try{equalizer=new Equalizer(0,player.getAudioSessionId());for(short b=0;b<equalizer.getNumberOfBands();b++)equalizer.setBandLevel(b,(short)PlayerDialogs.prefs(this).getInt("eq"+b,0));equalizer.setEnabled(true);}catch(Exception ignored){equalizer=null;}}if(loudness==null){try{loudness=new LoudnessEnhancer(player.getAudioSessionId());int gain=PlayerDialogs.prefs(this).getInt("gain",0);loudness.setTargetGain(gain*100);loudness.setEnabled(gain>0);}catch(Exception ignored){loudness=null;}}}
 void persist(){if(!ready||book==null)return;ArrayList<Book> list=Store.load(this);for(Book b:list)if(b.uri.equals(uri)){if(playing())b.lastReadAt=System.currentTimeMillis();b.position=position();b.duration=duration();b.chapterIndex=chapterIndex;b.speed=speed;}Store.save(this,list);}
 void metadata(){if(book==null)return;MediaMetadata.Builder builder=new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_DISPLAY_SUBTITLE,chapterTitle()).putLong(MediaMetadata.METADATA_KEY_DURATION,duration());if(cover!=null)builder.putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,cover);session.setMetadata(builder.build());}
 private PendingIntent action(String action,int request){return PendingIntent.getService(this,request,new Intent(this,PlaybackService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 void notice(){if(uri.isEmpty())return;session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS).setState(loading?PlaybackState.STATE_BUFFERING:playing()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,position(),speed).build());PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).putExtra("player",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder n=new Notification.Builder(this,"playback").setSmallIcon(R.drawable.ic_audivo).setContentTitle(title).setContentText("Chapter "+(chapterIndex+1)+" of "+chapterCount()+" · "+chapterTitle()).setContentIntent(open).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(playing()||loading).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_rew,"Back "+skipSeconds()+"s",action("back",1)).build()).addAction(new Notification.Action.Builder(playing()?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing()?"Pause":"Play",action("toggle",2)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_ff,"Forward "+skipSeconds()+"s",action("forward",3)).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));if(cover!=null)n.setLargeIcon(cover);startForeground(10,n.build());}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onDestroy(){persist();handler.removeCallbacksAndMessages(null);artwork.shutdownNow();metadataVersion++;chapters.shutdownNow();unregisterReceiver(noisy);releaseEffects();if(player!=null)player.release();manager.abandonAudioFocusRequest(focus);session.release();live=null;super.onDestroy();}
}

